python
def ribbonTotalsFirstQualifyingSlip(readings, k):
    a=readings
    out=[]
    total=0
    for x in a:
        total+=x
        out.append(total)
    return next((x for x in out if x>=k),-1)


java
class Solution {
  public int ribbonTotalsFirstQualifyingSlip(int[] readings, int k) {
    int[] a=readings; List<Integer> out=new ArrayList<>();
    {int total=0;for(int x:a){total+=x;out.add(total);}}
    for(int x:out)if(x>=k)return x;return -1;
  }
}
